node --input-type=module <<'NODE'
import fs from 'node:fs';
import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
const base='0f85cec7ea066ff626f7b2983f924468467c9717';
const read=p=>fs.readFileSync(p,'utf8');
const original=p=>execFileSync('git',['show',base+':'+p],{encoding:'utf8',maxBuffer:4*1024*1024});
const b=read('docs/development-backlog.md'),bo=original('docs/development-backlog.md');
const r=read('docs/v410-v49-recording-search-roadmap.md'),ro=original('docs/v410-v49-recording-search-roadmap.md');
for(const token of ['## v1.8.0 Release Trust Hardening Close-out','`candidate-only`','owner approval','auth/session contract']){assert.equal(bo.includes(token),false);assert.equal(b.includes(token),false);}
console.log('[confirmed-existing-failure] feature-scope-gate 실패 문구 4개는 기준 commit에도 없음. 이번 삭제로 생긴 회귀 아님');
const preserved=[['### 2026-08-14 v3.9.0 historical close-out status','## 현재 source roadmap: v4.1.0 Recording Foundation','## v4.1.0 녹화 기반'],['## Historical archive: v3.9.0',null,null]];
for(const [start,oldEnd,newEnd]of preserved){const a=bo.slice(bo.indexOf(start),oldEnd?bo.indexOf(oldEnd):undefined),c=b.slice(b.indexOf(start),newEnd?b.indexOf(newEnd):undefined);assert.equal(c,a);}
console.log('[pass] 축약 보류한 과거 본문 두 구간 바이트 불변');
const future=ro.slice(ro.indexOf('## v4.2.0 —'),ro.indexOf('## 버전 간 재작업 방지 규칙'));
let count=0;
for(const line of future.split('\n').filter(line=>/^\d+\. /.test(line))){if(line.includes('VARuleLens의 개념')){assert(r.includes('VARuleLens의 구현 참고는 위 라이선스 확인 경계'));}else assert(r.includes(line),line);count++;}
console.log('[pass] 미래 요구 '+count+'개 보존, VARuleLens 1개는 기존 라이선스 미확인 경계 반영');
for(let v=2;v<=9;v++){const part=r.split('## v4.'+v+'.0 —')[1]?.split('\n## ')[0];assert(part&&part.includes('완료 기준:'));}
console.log('[pass] v4.2~v4.9 목표 및 완료 기준 유지');
for(const token of ['영속 녹화 순서','PTS/DTS','UTC 매핑','partial','pin·hold','tombstone','disk reserve','SQLite','unknown','손상 거부','회귀 fixture'])assert(r.includes(token),token);
console.log('[pass] 시간·식별·보존·복구 핵심 경계 명시');
assert(b.includes('backlog 전체 축약은 보류'));assert(b.includes('외부 서비스·실기기 검증은 사용자 제외'));assert(r.includes('아직 구현 완료로 판정하지 않은'));
console.log('[pass] 보류·계획·검증 제외 구분');
for(const p of ['docs/development-backlog.md','docs/v410-v49-recording-search-roadmap.md']){const raw=original(p);const hash=execFileSync('git',['hash-object','--stdin'],{input:raw,encoding:'utf8'}).trim();assert.equal(hash,execFileSync('git',['rev-parse',base+':'+p],{encoding:'utf8'}).trim());}
execFileSync('git',['merge-base','--is-ancestor',base,'HEAD']);
console.log('[pass] 유지 이력 원본 commit/blob 재조회 일치');
NODE
